constexpr double kPi = 3.141592653589793;
constexpr double kTau = 2 * kPi;

struct Tag {
    int code;
    std::string value;
};
using Tags = std::vector<Tag>;

Tags parse_template(const char* text) {
    Tags tags;
    std::istringstream in(text);
    std::string code, value;
    while (std::getline(in, code) && std::getline(in, value)) tags.push_back({std::stoi(code), value});
    return tags;
}

std::string num(double x) { return pyfmt::repr(x); }
std::string handle_str(unsigned h) {
    char buf[32];
    std::snprintf(buf, sizeof(buf), "%X", h);
    return buf;
}

/// Python's float % (the result has the sign of the divisor).
double py_mod(double x, double y) {
    double mod = std::fmod(x, y);
    if (mod != 0.0) {
        if ((y < 0) != (mod < 0)) mod += y;
    } else {
        mod = std::copysign(0.0, y);
    }
    return mod;
}

bool isclose(double a, double b, double rel_tol = 1e-9, double abs_tol = 0.0) {
    if (a == b) return true;
    return std::fabs(a - b) <= std::max(rel_tol * std::max(std::fabs(a), std::fabs(b)), abs_tol);
}

// ---------------------------------------------------------------------------
// ezdxf.zoom.extents: bounding box of the entities' path control vertices
// ---------------------------------------------------------------------------

struct BBox2 {
    bool has_data = false;
    double minx = 0, miny = 0, maxx = 0, maxy = 0;
    void add(double x, double y) {
        if (!has_data) {
            minx = maxx = x;
            miny = maxy = y;
            has_data = true;
            return;
        }
        minx = std::min(minx, x);
        miny = std::min(miny, y);
        maxx = std::max(maxx, x);
        maxy = std::max(maxy, y);
    }
    void add(const BBox2& o) {
        if (!o.has_data) return;
        add(o.minx, o.miny);
        add(o.maxx, o.maxy);
    }
};

/// ezdxf's arc_angle_span_rad
double arc_angle_span_rad(double start, double end) {
    if (isclose(start, end, 1e-9, 1e-15)) return 0.0;
    start = py_mod(start, kTau);
    if (isclose(start, py_mod(end, kTau), 1e-9, 1e-15)) return kTau;
    if (!isclose(end, kTau, 1e-9, 1e-15)) end = py_mod(end, kTau);
    if (end < start) end += kTau;
    return end - start;
}

/// Control vertices of ezdxf's cubic Bezier approximation of an elliptic arc in the XY plane
/// (path.add_ellipse with cubic_bezier_from_ellipse).
BBox2 ellipse_bbox(double cx, double cy, double major_x, double major_y, double ratio, double start_param,
                   double end_param) {
    BBox2 box;
    const double param_span = arc_angle_span_rad(start_param, end_param);
    if (std::fabs(param_span) < 1e-9) return box;
    // minor axis = extrusion (0, 0, 1) x major axis, scaled to |major| * ratio
    const double major_len = std::sqrt(major_x * major_x + major_y * major_y);
    const double minor_len = major_len * ratio;
    // extrusion (0, 0, 1) x major_axis, normalized to the minor radius (Vec3.normalize)
    const double mx = -major_y, my = major_x;
    const double mfactor = minor_len / std::sqrt(mx * mx + my * my);
    const double minor_x = mx * mfactor, minor_y = my * mfactor;
    auto transform = [&](double px, double py) {
        return std::pair<double, double>{cx + major_x * px + minor_x * py, cy + major_y * px + minor_y * py};
    };
    // path start: the ellipse start point
    {
        const double xf = 1.0 / major_len;
        const double yf = 1.0 / std::sqrt(minor_x * minor_x + minor_y * minor_y);
        const double x_unit_x = major_x * xf, x_unit_y = major_y * xf;
        const double y_unit_x = minor_x * yf, y_unit_y = minor_y * yf;
        const double x = std::cos(start_param) * major_len;
        const double y = std::sin(start_param) * minor_len;
        box.add(cx + x * x_unit_x + y * y_unit_x, cy + x * x_unit_y + y * y_unit_y);
    }
    double start_angle = py_mod(start_param, kTau);
    double end_angle = start_angle + param_span;
    while (start_angle > end_angle) end_angle += kTau;
    const double delta_angle = end_angle - start_angle;
    const int arc_count = std::max(static_cast<int>(std::ceil(delta_angle / kPi * 2.0)), 1);
    const double segment_angle = delta_angle / arc_count;
    const double tangent_length = 4.0 / 3.0 * std::tan(segment_angle / 4.0);
    double angle = start_angle;
    double ex = std::cos(angle), ey = std::sin(angle);
    for (int i = 0; i < arc_count; ++i) {
        const double sx = ex, sy = ey;
        angle += segment_angle;
        ex = std::cos(angle);
        ey = std::sin(angle);
        for (const auto& [px, py] : {std::pair<double, double>{sx, sy},
                                     {sx - sy * tangent_length, sy + sx * tangent_length},
                                     {ex + ey * tangent_length, ey - ex * tangent_length},
                                     {ex, ey}}) {
            const auto [x, y] = transform(px, py);
            box.add(x, y);
        }
    }
    return box;
}

/// ezdxf's BSpline as far as path.add_spline needs it.
struct EzBSpline {
    std::vector<std::array<double, 3>> control_points;
    int order = 4;
    std::vector<double> knots;
    std::vector<double> weights;

    int degree() const { return order - 1; }
    int count() const { return static_cast<int>(control_points.size()); }
    double max_t() const { return knots.back(); }
    bool is_rational() const { return !weights.empty(); }
    bool is_clamped() const {
        auto all_equal = [](auto b, auto e) { return std::all_of(b, e, [&](double v) { return v == *b; }); };
        return all_equal(knots.begin(), knots.begin() + order) && all_equal(knots.end() - order, knots.end());
    }

    int find_span(double u) const {
        const int n = count();
        if (u >= knots[n]) return n - 1;
        const int p = order - 1;
        if (knots[p] == 0.0) {
            return static_cast<int>(std::upper_bound(knots.begin() + p, knots.begin() + n, u) - knots.begin()) - 1;
        }
        int span = 0;
        while (knots[span] <= u && span < n) ++span;
        return span - 1;
    }

    std::vector<double> basis_funcs(int span, double u) const {
        std::vector<double> N(order, 0.0), left(order, 0.0), right(order, 0.0);
        N[0] = 1.0;
        for (int j = 1; j < order; ++j) {
            left[j] = u - knots[std::max(0, span + 1 - j)];
            right[j] = knots[span + j] - u;
            double saved = 0.0;
            for (int r = 0; r < j; ++r) {
                const double temp = N[r] / (right[r + 1] + left[j - r]);
                N[r] = saved + right[r + 1] * temp;
                saved = left[j - r] * temp;
            }
            N[j] = saved;
        }
        if (is_rational()) {
            const int start = span - order + 1;
            if (start >= 0 && start + order <= static_cast<int>(weights.size())) {
                std::vector<double> products(order);
                double s = 0.0;
                for (int i = 0; i < order; ++i) {
                    products[i] = N[i] * weights[start + i];
                    s += products[i];
                }
                if (s != 0.0) {
                    for (auto& p : products) p /= s;
                    return products;
                }
            }
        }
        return N;
    }

    std::array<double, 3> point(double u) const {
        if (isclose(u, max_t())) u = max_t();
        const int p = degree();
        const int span = find_span(u);
        const auto N = basis_funcs(span, u);
        std::array<double, 3> s{0, 0, 0};
        for (int i = 0; i <= p; ++i) {
            for (int k = 0; k < 3; ++k) s[k] += N[i] * control_points[span - p + i][k];
        }
        return s;
    }

    /// "The NURBS Book" A5.6, as ezdxf's bezier_decomposition.
    std::vector<std::vector<std::array<double, 3>>> bezier_decomposition() const {
        std::vector<std::vector<std::array<double, 3>>> out;
        const int n = count() - 1;
        const int p = degree();
        const int m = n + p + 1;
        int a = p, b = p + 1;
        std::vector<double> alphas(knots.size(), 0.0);
        std::vector<std::array<double, 3>> bezier_points(control_points.begin(), control_points.begin() + p + 1);
        while (b < m) {
            std::vector<std::array<double, 3>> next(p + 1, {0, 0, 0});
            const int i = b;
            while (b < m && isclose(knots[b + 1], knots[b])) ++b;
            const int mult = b - i + 1;
            if (mult < p) {
                const double numer = knots[b] - knots[a];
                for (int j = p; j > mult; --j) alphas[j - mult - 1] = numer / (knots[a + j] - knots[a]);
                const int r = p - mult;
                for (int j = 1; j <= r; ++j) {
                    const int save = r - j;
                    const int s = mult + j;
                    for (int k = p; k >= s; --k) {
                        const double alpha = alphas[k - s];
                        for (int c = 0; c < 3; ++c) {
                            bezier_points[k][c] = bezier_points[k][c] * alpha + bezier_points[k - 1][c] * (1.0 - alpha);
                        }
                    }
                    if (b < m) next[save] = bezier_points[p];
                }
            }
            out.push_back(bezier_points);
            if (b < m) {
                for (int k = p - mult; k <= p; ++k) next[k] = control_points[b - p + k];
                a = b;
                b += 1;
                bezier_points = next;
            }
        }
        return out;
    }

    /// The control vertices of path.add_spline (level 4).
    BBox2 path_bbox() const {
        BBox2 box;
        const auto start = point(0.0);
        box.add(start[0], start[1]);
        if (degree() == 3 && !is_rational() && is_clamped()) {
            for (const auto& curve : bezier_decomposition()) {
                for (const auto& p : curve) box.add(p[0], p[1]);
            }
            return box;
        }
        // cubic_bezier_approximation(level=4)
        std::vector<double> distances;
        for (std::size_t i = 1; i < control_points.size(); ++i) {
            const auto& p = control_points[i - 1];
            const auto& q = control_points[i];
            distances.push_back(std::sqrt((p[0] - q[0]) * (p[0] - q[0]) + (p[1] - q[1]) * (p[1] - q[1]) +
                                          (p[2] - q[2]) * (p[2] - q[2])));
        }
        double total = 0.0;
        for (double d : distances) total += d;  // Python sum (exact enough for a view)
        std::vector<double> params;
        if (std::fabs(total) > 1e-12) {
            params.push_back(0.0);
            double s = 0.0;
            for (std::size_t i = 0; i + 1 < distances.size(); ++i) {
                s += distances[i];
                params.push_back(s / total);
            }
            params.push_back(1.0);
        }
        if (params.empty()) return box;
        if (max_t() != 1.0) {
            for (auto& t : params) t *= max_t();
        }
        for (int level = 1; level < 4; ++level) {
            std::vector<double> sub;
            for (std::size_t i = 0; i + 1 < params.size(); ++i) {
                sub.push_back(params[i]);
                sub.push_back((params[i] + params[i + 1]) / 2.0);
            }
            sub.push_back(params.back());
            params = sub;
        }
        std::vector<std::array<double, 3>> pnts;
        for (double t : params) pnts.push_back(point(t));
        if (pnts.size() < 3) return box;
        // cubic_bezier_interpolation
        const std::size_t num = pnts.size() - 1;
        std::vector<double> a(num, 1.0), b(num, 4.0), c(num, 1.0);
        b[0] = 2.0;
        b[num - 1] = 7.0;
        a[num - 1] = 2.0;
        std::vector<std::array<double, 3>> rhs;
        auto lin = [](double f1, const std::array<double, 3>& p, double f2, const std::array<double, 3>& q) {
            return std::array<double, 3>{f1 * p[0] + f2 * q[0], f1 * p[1] + f2 * q[1], f1 * p[2] + f2 * q[2]};
        };
        rhs.push_back(lin(1.0, pnts[0], 2.0, pnts[1]));
        for (std::size_t i = 1; i + 1 < num; ++i) {
            const auto t = lin(2.0, pnts[i], 1.0, pnts[i + 1]);
            rhs.push_back({2.0 * t[0], 2.0 * t[1], 2.0 * t[2]});
        }
        rhs.push_back(lin(8.0, pnts[num - 1], 1.0, pnts[num]));
        std::vector<std::array<double, 3>> cp1(num);
        for (int col = 0; col < 3; ++col) {
            std::vector<double> u(num, 0.0), gam(num, 0.0);
            double bet = b[0];
            u[0] = rhs[0][col] / bet;
            for (std::size_t j = 1; j < num; ++j) {
                gam[j] = c[j - 1] / bet;
                bet = b[j] - a[j] * gam[j];
                u[j] = (rhs[j][col] - a[j] * u[j - 1]) / bet;
            }
            for (std::size_t j = num - 1; j-- > 0;) u[j] -= gam[j + 1] * u[j + 1];
            for (std::size_t j = 0; j < num; ++j) cp1[j][col] = u[j];
        }
        std::vector<std::array<double, 3>> cp2;
        for (std::size_t i = 1; i < num; ++i) {
            cp2.push_back({pnts[i][0] * 2.0 - cp1[i][0], pnts[i][1] * 2.0 - cp1[i][1], pnts[i][2] * 2.0 - cp1[i][2]});
        }
        cp2.push_back({(cp1[num - 1][0] + pnts[num][0]) / 2.0, (cp1[num - 1][1] + pnts[num][1]) / 2.0,
                       (cp1[num - 1][2] + pnts[num][2]) / 2.0});
        for (std::size_t i = 0; i < num; ++i) {
            for (const auto* p : {&pnts[i], &cp1[i], &cp2[i], &pnts[i + 1]}) box.add((*p)[0], (*p)[1]);
        }
        return box;
    }
};

// ---------------------------------------------------------------------------
// Encodings
// ---------------------------------------------------------------------------

/// UTF-8 to cp1252 with ezdxf's "dxfreplace" error handler (\U+XXXX).
std::string to_cp1252(const std::string& utf8) {
    static const char32_t high[32] = {0x20AC, 0,      0x201A, 0x0192, 0x201E, 0x2026, 0x2020, 0x2021,
                                      0x02C6, 0x2030, 0x0160, 0x2039, 0x0152, 0,      0x017D, 0,
                                      0,      0x2018, 0x2019, 0x201C, 0x201D, 0x2022, 0x2013, 0x2014,
                                      0x02DC, 0x2122, 0x0161, 0x203A, 0x0153, 0,      0x017E, 0x0178};
    std::string out;
    const auto* p = reinterpret_cast<const unsigned char*>(utf8.data());
    const auto* end = p + utf8.size();
    while (p < end) {
        char32_t cp = *p;
        int extra = cp >= 0xF0 ? 3 : cp >= 0xE0 ? 2 : cp >= 0xC0 ? 1 : 0;
        if (extra) cp &= (0x3F >> extra);
        ++p;
        for (int i = 0; i < extra && p < end; ++i, ++p) cp = (cp << 6) | (*p & 0x3F);
        if (cp < 0x80 || (cp >= 0xA0 && cp <= 0xFF)) {
            out += static_cast<char>(cp);
            continue;
        }
        bool done = false;
        for (int i = 0; i < 32; ++i) {
            if (high[i] == cp && cp != 0) {
                out += static_cast<char>(0x80 + i);
                done = true;
                break;
            }
        }
        if (!done) {
            char buf[16];
            std::snprintf(buf, sizeof(buf), "\\U+%04X", static_cast<unsigned>(cp));
            out += buf;
        }
    }
    return out;
}

enum class TagType { STRING, BYTE, INT16, INT32, INT64, DOUBLE, BINARY };

TagType tag_type(int code) {
    auto in = [code](int a, int b) { return code >= a && code < b; };
    if (in(310, 320) || code == 1004) return TagType::BINARY;
    if (in(290, 300)) return TagType::BYTE;
    if (in(60, 80) || in(170, 180) || in(270, 290) || in(370, 390) || in(400, 410) || in(1060, 1071)) {
        return TagType::INT16;
    }
    if (in(90, 100) || in(420, 430) || in(440, 450) || in(450, 460) || code == 1071) return TagType::INT32;
    if (in(160, 170)) return TagType::INT64;
    if (in(10, 60) || in(110, 150) || in(210, 240) || in(460, 470) || in(1010, 1060)) return TagType::DOUBLE;
    return TagType::STRING;
}

void write_le(std::string& out, std::uint64_t v, int bytes) {
    for (int i = 0; i < bytes; ++i) out += static_cast<char>((v >> (8 * i)) & 0xFF);
}

/// ezdxf's BinaryTagWriter.
std::string binary_dxf(const Tags& tags, bool r12, bool utf8) {
    std::string out("AutoCAD Binary DXF\r\n\x1a\x00", 22);
    for (const Tag& t : tags) {
        if (tag_type(t.code) == TagType::BINARY) {
            // hex string to bytes, in chunks of 127
            std::string data;
            for (std::size_t i = 0; i + 1 < t.value.size(); i += 2) {
                data += static_cast<char>(std::stoi(t.value.substr(i, 2), nullptr, 16));
            }
            for (std::size_t i = 0; i < data.size(); i += 127) {
                if (r12 && t.code >= 1000) out += '\xff';
                write_le(out, static_cast<std::uint64_t>(t.code), 2);
                const std::string chunk = data.substr(i, 127);
                out += static_cast<char>(chunk.size());
                out += chunk;
            }
            continue;
        }
        if (r12) {
            if (t.code >= 1000) {
                out += '\xff';
                write_le(out, static_cast<std::uint64_t>(t.code), 2);
            } else {
                write_le(out, static_cast<std::uint64_t>(t.code), 1);
            }
        } else {
            write_le(out, static_cast<std::uint64_t>(t.code), 2);
        }
        switch (tag_type(t.code)) {
            case TagType::BYTE: write_le(out, static_cast<std::uint64_t>(std::stoll(t.value)), 1); break;
            case TagType::INT16: write_le(out, static_cast<std::uint64_t>(std::stoll(t.value)), 2); break;
            case TagType::INT32: write_le(out, static_cast<std::uint64_t>(std::stoll(t.value)), 4); break;
            case TagType::INT64: write_le(out, static_cast<std::uint64_t>(std::stoll(t.value)), 8); break;
            case TagType::DOUBLE: {
                const double d = std::stod(t.value);
                std::uint64_t bits;
                std::memcpy(&bits, &d, sizeof(bits));
                write_le(out, bits, 8);
                break;
            }
            default:
                out += utf8 ? t.value : to_cp1252(t.value);
                out += '\0';
        }
    }
    return out;
}

/// ezdxf's juliandate().
double juliandate(const std::tm& t) {
    const double y = (t.tm_year + 1900) + (static_cast<double>(t.tm_mon + 1) - 2.85) / 12.0;
    const double A = std::floor(367.0 * y) - 1.75 * std::floor(y) + t.tm_mday;
    const double B = std::floor(A) - 0.75 * std::floor(y / 100.0);
    const double julian = std::floor(B) + 1721115.0;
    const double seconds = t.tm_hour * 3600.0 + t.tm_min * 60.0 + t.tm_sec;
    return julian + seconds / 86400.0;
}

std::string guid() {
    static std::mt19937_64 rng(std::random_device{}());
    std::uniform_int_distribution<unsigned> d(0, 15);
    const char* hex = "0123456789ABCDEF";
    std::string s = "{";
    for (int i = 0; i < 32; ++i) {
        if (i == 8 || i == 12 || i == 16 || i == 20) s += '-';
        unsigned v = d(rng);
        if (i == 12) v = 4;                 // version 4
        if (i == 16) v = 8 + (v & 3);       // variant
        s += hex[v];
    }
    return s + "}";
}

/// The index of the tag after the 0-tag starting at `i` (the next 0-tag).
/// ezdxf's table entry names are case-insensitive.
bool same_name(const std::string& a, const std::string& b) {
    if (a.size() != b.size()) return false;
    for (std::size_t i = 0; i < a.size(); ++i) {
        if (std::tolower(static_cast<unsigned char>(a[i])) != std::tolower(static_cast<unsigned char>(b[i]))) return false;
    }
    return true;
}

bool contains_name(const std::vector<std::string>& names, const std::string& name) {
    return std::any_of(names.begin(), names.end(), [&](const std::string& n) { return same_name(n, name); });
}

std::size_t record_end(const Tags& tags, std::size_t i) {
    std::size_t j = i + 1;
    while (j < tags.size() && tags[j].code != 0) ++j;
    return j;
}

